with open(MARS_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    aries_json = "      Aries: " + json.dumps(aries_data, indent=8) + ","
    new_content = content[:insertion_point] + "\n" + aries_json + content[insertion_point:]
    
    with open(MARS_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Mars in Aries to mars.js")
else:
    print("Could not find signs object in mars.js")
